Here's the corrected version of Assistant B's answer:

```cpp
#include <iostream>
#include <vector>

int sequence(int n) {
    std::vector<int> seq = {0, -1, -1};

    for (int i = 3; i <= n; ++i) {
        int next_number = seq[i - 1] + seq[i - 2] + seq[i - 3];
        seq.push_back(next_number);
    }

    return seq[n];
}

int main() {
    int n;
    std::cout << "Enter the value of n: ";
    std::cin >> n;

    int seq_num = sequence(n);
    std::cout << "The " << n << "th number in the sequence is: " << seq_num << std::endl;

    return 0;
}
